/** A QueryParser which constructs queries to search multiple fields. */
public class MultiFieldQueryParser extends QueryParser {
  protected String[] fields;
  protected Map<String, Float> boosts;

  private Map<String, Float> simpleWeights;
  private int simpleFlags;
  private BooleanClause.Occur simpleDefaultOperator;
  private Analyzer simpleAnalyzer;
  private SimpleSyntaxState simpleParseState;

  private String phraseField;
  private String phraseQueryText;
  private int phraseSlop;
  private boolean phraseInOrder;
  private Query phraseContents;

  private org.apache.lucene.queryparser.xml.QueryBuilder xmlFactory;
  private Analyzer xmlAnalyzer;
